class Solution {
public:
    int total = 0;
    void go(vector<int>& nums, int i, int cur) {
        if (i == (int)nums.size()) {
            total += cur;
            return;
        }
        go(nums, i + 1, cur ^ nums[i]);
        go(nums, i + 1, cur);
    }
    int subsetXORSum(vector<int>& nums) {
        go(nums, 0, 0);
        return total;
    }
};
